import type { ImageManifest, ImageMeta } from '../models/content.models';
import manifest from '../../../assets/content/images.json';

/** Generated by `npm run images`. Do not edit by hand. */
export const IMAGE_MANIFEST = manifest as ImageManifest;

export function imageMeta(id: string): ImageMeta {
  const meta = IMAGE_MANIFEST[id];
  if (!meta) {
    throw new Error(
      `Unknown image id "${id}". Add it to scripts/images.config.json and run npm run images.`,
    );
  }
  return meta;
}

export const IMAGE_BASE = '/assets/images';
